<?php if (!empty($_SESSION['bulk_report'])): $bulkReport=$_SESSION['bulk_report']; ?>
<section class="card spaced" aria-label="Resultado de carga masiva"><h2>Resultado de la última carga masiva</h2><p class="muted"><?= (int)$bulkReport['file_count'] ?> PDF recibidos · <?= (int)$bulkReport['saved'] ?> historias guardadas · <?= (int)$bulkReport['reused'] ?> ya registradas · <?= (int)$bulkReport['failed'] ?> resultados con errores · <?= (int)$bulkReport['blocked'] ?> grupos sin guardar.</p>
<div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Archivos</th><th scope="col" role="columnheader">Paciente / atención</th><th scope="col" role="columnheader">Resultado</th></tr></thead><tbody role="rowgroup">
<?php foreach($bulkReport['results'] as $result): ?><tr role="row"><td role="cell" data-label="Archivos" class="bulk-files"><?php foreach($result['files'] as $file): ?><div><?= h($file) ?></div><?php endforeach ?></td><td role="cell" data-label="Paciente / atención"><?= h($result['patient'] ?? 'No identificado') ?><small><?= h($result['document'] ?? '') ?></small><small><?= isset($result['date']) ? h(date('d/m/Y',strtotime($result['date']))) : '' ?></small></td><td role="cell" data-label="Resultado" class="bulk-result"><span class="pill"><?= h(['saved'=>'Guardada','reused'=>'Ya registrada','error'=>'Revisar','blocked'=>'Sin guardar'][$result['status']]) ?></span><p><?= h($result['message']) ?></p></td></tr><?php endforeach ?>
</tbody></table></div></section><?php endif ?>
